#!/usr/bin/env bash
# Simple user-local install without requiring a full pip build.
# Places the `sigil` command and data under ~/.local

set -euo pipefail

PREFIX="${HOME}/.local"
BINDIR="${PREFIX}/bin"
LIBDIR="${PREFIX}/share/sigil-creator"

echo "Installing sigil-creator to ${PREFIX} ..."

mkdir -p "${BINDIR}" "${LIBDIR}"

# Copy the whole package tree so relative imports + data work
cp -a src/sigil_creator "${LIBDIR}/"

# Wrapper so PYTHONPATH points at the parent of the package
cat > "${BINDIR}/sigil" <<'WRAPPER'
#!/usr/bin/env bash
# Auto-generated by sigil-creator install.sh
LIBDIR="${HOME}/.local/share/sigil-creator"
export PYTHONPATH="${LIBDIR}${PYTHONPATH:+:$PYTHONPATH}"
exec python3 -m sigil_creator.cli "$@"
WRAPPER
chmod +x "${BINDIR}/sigil"

# Optional convenience names (same binary; use subcommands)
ln -sf sigil "${BINDIR}/sigil-reduce" 2>/dev/null || true
ln -sf sigil "${BINDIR}/sigil-numbers" 2>/dev/null || true

echo
echo "Installed."
echo "  Ensure ${BINDIR} is on your PATH, e.g. in ~/.bashrc:"
echo "    export PATH=\"\$HOME/.local/bin:\$PATH\""
echo
echo "Then try:"
echo "  sigil guide"
echo "  sigil reduce \"I am calm and focused\""
echo "  sigil profiles"
echo "  sigil methods"
echo "  sigil show-profile chaos_minimal"
